const barRect = bar.getBoundingClientRect();
const leadRect = lead.getBoundingClientRect();
const p2Rect = p2.getBoundingClientRect();

const overlapsLead = !(barRect.right < leadRect.left || barRect.left > leadRect.right || barRect.bottom < leadRect.top || barRect.top > leadRect.bottom);
const overlapsP2 = !(barRect.right < p2Rect.left || barRect.left > p2Rect.right || barRect.bottom < p2Rect.top || barRect.top > p2Rect.bottom);

